package in.recallradar;

import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.web.server.ResponseStatusException;
import java.io.*;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import java.util.regex.*;
import org.apache.pdfbox.Loader;
import org.apache.pdfbox.text.PDFTextStripper;

@Service @Transactional class RecallNoticeService {
 private final RecallNoticeRepository notices; private final RecallNoticeFactRepository facts; private final InventoryLotRepository lots; private final IngredientRepository ingredients; private final SupplierRepository suppliers; private final InventoryBalanceRepository balances; private final RecallService recalls; private final TenantService tenants; private final AuditService audit;
 RecallNoticeService(RecallNoticeRepository n,RecallNoticeFactRepository f,InventoryLotRepository l,IngredientRepository i,SupplierRepository s,InventoryBalanceRepository b,RecallService r,TenantService t,AuditService a){notices=n;facts=f;lots=l;ingredients=i;suppliers=s;balances=b;recalls=r;tenants=t;audit=a;}
 List<RecallNoticeResponse> list(Membership m){return notices.findByOrganizationIdOrderByCreatedAtDesc(m.organizationId).stream().map(x->response(m,x)).toList();}
 RecallNoticeResponse get(Membership m,UUID id){return response(m,notice(m,id));}
 RecallNoticeResponse reference(Membership m,RecallNoticeReferenceRequest request){tenants.requireMasterDataEditor(m);var notice=notices.save(new RecallNotice(m.organizationId,m.userId,"REFERENCE",null,null,request.reference().trim()));saveFact(notice,"notice_reference",request.reference().trim(),60,"Typed supplier/authority reference",true);refresh(notice);audit.record(m,"RECALL_NOTICE_CREATED","RECALL_NOTICE",notice.id,"Typed reference");return response(m,notice);}
 RecallNoticeResponse upload(Membership m,MultipartFile file){tenants.requireMasterDataEditor(m);if(file.isEmpty())throw bad("Choose a notice file to upload.");if(file.getSize()>10_000_000)throw bad("A recall notice may be at most 10 MB.");String name=cleanName(file.getOriginalFilename());String extension=extension(name);if(!Set.of("csv","txt","pdf","jpg","jpeg","png").contains(extension))throw bad("Use CSV, TXT, PDF, JPG, or PNG for a recall notice.");String path=store(file,name);var notice=notices.save(new RecallNotice(m.organizationId,m.userId,extension.toUpperCase(Locale.ROOT),name,path,null));if(extension.equals("csv"))extractCsv(notice,file);else if(extension.equals("txt"))extractText(notice,read(file),"Text notice");else if(extension.equals("pdf"))extractPdf(notice,file);else {saveFact(notice,"document_reference",name,35,"Uploaded "+extension.toUpperCase(Locale.ROOT)+" file",true);saveFact(notice,"review_instruction","Read the document and confirm the supplier, ingredient, or lot number below.",100,"System",false);}refresh(notice);audit.record(m,"RECALL_NOTICE_UPLOADED","RECALL_NOTICE",notice.id,name);return response(m,notice);}
 RecallNoticeResponse confirmFact(Membership m,UUID noticeId,UUID factId,ConfirmRecallNoticeFactRequest request){tenants.requireMasterDataEditor(m);var notice=notice(m,noticeId);if(notice.status==RecallNoticeStatus.CONFIRMED)throw bad("This notice has already created a recall.");var fact=facts.findByIdAndNoticeId(factId,notice.id).orElseThrow(()->missing("Notice fact"));fact.confirmedValue=request.value().trim();fact.requiresResolution=false;refresh(notice);audit.record(m,"RECALL_NOTICE_FACT_CONFIRMED","RECALL_NOTICE",notice.id,fact.fieldName);return response(m,notice);}
 RecallNoticeResponse confirm(Membership m,UUID id,ConfirmRecallNoticeRequest request){tenants.requireMasterDataEditor(m);var notice=notice(m,id);if(notice.status==RecallNoticeStatus.CONFIRMED)return response(m,notice);if(facts.findByNoticeIdOrderByCreatedAt(notice.id).stream().anyMatch(x->x.requiresResolution))throw bad("Confirm every uncertain extracted fact before creating a recall.");var lot=lots.findByIdAndOrganizationId(request.lotId(),m.organizationId).orElseThrow(()->missing("Matched lot"));String title=request.title()==null||request.title().isBlank()?defaultTitle(notice,lot):request.title().trim();var recall=recalls.create(m,new RecallRequest(lot.id,title));notice.confirmedRecallId=UUID.fromString(recall.id());notice.confirmedAt=Instant.now();notice.status=RecallNoticeStatus.CONFIRMED;audit.record(m,"RECALL_NOTICE_CONFIRMED","RECALL_NOTICE",notice.id,recall.id());return response(m,notice);}
 private RecallNotice notice(Membership m,UUID id){return notices.findByIdAndOrganizationId(id,m.organizationId).orElseThrow(()->missing("Recall notice"));}
 private void extractCsv(RecallNotice notice,MultipartFile file){String[] lines=read(file).replace("\r","").split("\n");if(lines.length<2){saveFact(notice,"document_reference",notice.fileName,35,"CSV header",true);return;}String[] header=split(lines[0]);String[] row=split(lines[1]);for(int i=0;i<header.length&&i<row.length;i++){String field=normalField(header[i]);if(field!=null&&!row[i].isBlank())saveFact(notice,field,row[i].trim(),100,"CSV row 2: "+header[i].trim(),false);}if(facts.findByNoticeIdOrderByCreatedAt(notice.id).isEmpty())saveFact(notice,"document_reference",notice.fileName,35,"CSV row 2",true);}
 private void extractText(RecallNotice notice,String text,String source){Map<String,String> patterns=Map.of("supplier","(?im)^(?:supplier|manufacturer)\\s*[:\\-]\\s*(.+)$","ingredient","(?im)^(?:ingredient|product|food)\\s*[:\\-]\\s*(.+)$","batch_number","(?im)^(?:batch|lot|batch number|lot number)\\s*[:#\\-]\\s*(.+)$","reason","(?im)^(?:reason|hazard|issue)\\s*[:\\-]\\s*(.+)$");for(var entry:patterns.entrySet()){var match=Pattern.compile(entry.getValue()).matcher(text);if(match.find())saveFact(notice,entry.getKey(),match.group(1).trim(),82,source,false);}if(facts.findByNoticeIdOrderByCreatedAt(notice.id).isEmpty())saveFact(notice,"document_reference",notice.fileName,35,source,true);}
 private void extractPdf(RecallNotice notice,MultipartFile file){try(var document=Loader.loadPDF(file.getBytes())){extractText(notice,new PDFTextStripper().getText(document),"PDF text");}catch(Exception error){saveFact(notice,"document_reference",notice.fileName,35,"PDF could not be read as text",true);}}
 private void saveFact(RecallNotice n,String field,String value,int confidence,String source,boolean unresolved){facts.save(new RecallNoticeFact(n.id,field,value,confidence,source,unresolved));}
 private void refresh(RecallNotice n){if(n.status!=RecallNoticeStatus.CONFIRMED)n.status=facts.findByNoticeIdOrderByCreatedAt(n.id).stream().anyMatch(x->x.requiresResolution)?RecallNoticeStatus.NEEDS_REVIEW:RecallNoticeStatus.READY_TO_CONFIRM;}
 private RecallNoticeResponse response(Membership m,RecallNotice n){var values=facts.findByNoticeIdOrderByCreatedAt(n.id);return new RecallNoticeResponse(n.id.toString(),n.status,n.sourceType,n.fileName,n.typedReference,n.createdAt,values.stream().map(x->new RecallNoticeFactResponse(x.id.toString(),x.fieldName,x.extractedValue,x.confirmedValue,x.confidence,x.sourceReference,x.requiresResolution)).toList(),candidates(m,values),n.confirmedRecallId==null?null:n.confirmedRecallId.toString());}
 private List<RecallNoticeCandidateResponse> candidates(Membership m,List<RecallNoticeFact> facts){Map<String,String> values=new HashMap<>();facts.forEach(x->values.put(x.fieldName,normalize(x.value())));return lots.findByOrganizationIdOrderByReceivedAtDesc(m.organizationId).stream().map(lot->{var ingredient=ingredients.findByIdAndOrganizationId(lot.ingredientId,m.organizationId).orElseThrow();var supplier=suppliers.findByIdAndOrganizationId(lot.supplierId,m.organizationId).orElseThrow();List<String> reasons=new ArrayList<>();int score=0;if(match(values.get("batch_number"),lot.supplierBatchNumber)){score+=65;reasons.add("Lot number matches the notice");}if(match(values.get("supplier"),supplier.name)){score+=20;reasons.add("Supplier matches the notice");}if(match(values.get("ingredient"),ingredient.name)){score+=15;reasons.add("Ingredient matches the notice");}BigDecimal qty=balances.findByLotId(lot.id).stream().map(x->x.quantity).reduce(BigDecimal.ZERO,BigDecimal::add);return new RecallNoticeCandidateResponse(lot.id.toString(),ingredient.name,supplier.name,lot.supplierBatchNumber,lot.expiryDate==null?null:lot.expiryDate.toString(),qty.stripTrailingZeros().toPlainString(),lot.unit,score,reasons);}).filter(x->x.score()>0).sorted(Comparator.comparingInt(RecallNoticeCandidateResponse::score).reversed()).limit(8).toList();}
 private boolean match(String expected,String actual){if(expected==null||expected.isBlank())return false;String normalized=normalize(actual);return normalized.contains(expected)||expected.contains(normalized)||distance(expected,normalized)<=Math.max(1,Math.min(expected.length(),normalized.length())/5);}
 private int distance(String a,String b){int[] p=new int[b.length()+1];for(int j=0;j<=b.length();j++)p[j]=j;for(int i=1;i<=a.length();i++){int[] c=new int[b.length()+1];c[0]=i;for(int j=1;j<=b.length();j++)c[j]=Math.min(Math.min(c[j-1]+1,p[j]+1),p[j-1]+(a.charAt(i-1)==b.charAt(j-1)?0:1));p=c;}return p[b.length()];}
 private String defaultTitle(RecallNotice n,InventoryLot lot){return "Recall notice — "+lot.supplierBatchNumber;}
 private String cleanName(String name){String clean=name==null?"recall-notice":Paths.get(name).getFileName().toString();return clean.replaceAll("[^A-Za-z0-9._ -]","_");}
 private String extension(String name){int at=name.lastIndexOf('.');return at<0?"":name.substring(at+1).toLowerCase(Locale.ROOT);}
 private String store(MultipartFile file,String name){try{Path dir=Paths.get(System.getProperty("java.io.tmpdir"),"recallradar-notices");Files.createDirectories(dir);Path target=dir.resolve(UUID.randomUUID()+"-"+name);try(InputStream input=file.getInputStream()){Files.copy(input,target,StandardCopyOption.REPLACE_EXISTING);}return target.toString();}catch(IOException e){throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR,"Could not store the recall notice.");}}
 private String read(MultipartFile file){try{return new String(file.getBytes(),StandardCharsets.UTF_8);}catch(IOException e){throw bad("Could not read this file.");}}
 private String[] split(String row){return row.split(",(?=(?:[^\\\"]*\\\"[^\\\"]*\\\")*[^\\\"]*$)",-1);}
 private String normalField(String input){String x=normalize(input).replace(' ','_');return switch(x){case "supplier","supplier_name","manufacturer"->"supplier";case "ingredient","product","food","product_name"->"ingredient";case "batch","lot","batch_number","lot_number"->"batch_number";case "reason","hazard","issue"->"reason";default->null;};}
 private String normalize(String value){return value==null?"":value.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+"," ").trim();}
 private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private ResponseStatusException missing(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m+" not found.");}
}
